<header class="top">
  <span class="dot"></span>
  <h1>My Bookmarks</h1>
</header>

<div class="wrap">
  <section class="capture">
    <h2>Save a link</h2>
    <div class="url-row">
      <input id="url" type="url" placeholder="Paste or type a link, e.g. https://example.com/article" autocomplete="off" />
      <button id="fetchBtn">Save link</button>
    </div>

    <div class="fetching" id="fetching"><span class="spinner"></span> Reading the page…</div>

    <div class="details" id="details">
      <span class="autofill-note" id="autofillNote">✓ Filled in automatically from the page — adjust anything you like</span>
      <div class="field">
        <label for="title">Title</label>
        <input id="title" type="text" />
      </div>
      <div class="field">
        <label for="desc">Description</label>
        <textarea id="desc" rows="2"></textarea>
      </div>
      <div class="field">
        <label for="tags">Tags</label>
        <input id="tags" type="text" placeholder="e.g. design, reference" />
        <div class="tag-input-hint">Separate tags with commas</div>
      </div>
      <div class="field">
        <label for="note">Your note (optional)</label>
        <textarea id="note" rows="2" placeholder="Why you saved it, what to remember…"></textarea>
      </div>
      <div class="actions">
        <button id="saveBtn">Add to collection</button>
        <button class="secondary" id="cancelBtn">Cancel</button>
      </div>
    </div>
  </section>

  <section class="collection">
    <h2>My collection <span class="count" id="count"></span></h2>
    <div id="list"></div>
  </section>
</div>

<script>
// --- Simulated page-metadata lookup (prototype stand-in for real page reading) ---
const KNOWN = {
  "stripe.com": { title: "Stripe | Payment Processing Platform for the Internet",
    desc: "Stripe powers online payments for businesses of every size with a suite of developer-first APIs." },
  "figma.com": { title: "Figma: The Collaborative Interface Design Tool",
    desc: "Design, prototype, and gather feedback all in one place with Figma." },
  "nytimes.com": { title: "Breaking News, World News & Multimedia — The New York Times",
    desc: "Live news, investigations, opinion, photos and video from the reporters of The New York Times." },
  "css-tricks.com": { title: "A Complete Guide to Flexbox | CSS-Tricks",
    desc: "Our comprehensive guide to CSS flexbox layout. This complete guide explains everything about flexbox." }
};
function simulateFetch(url) {
  let host = "", path = "";
  try { const u = new URL(url); host = u.hostname.replace(/^www\./,""); path = u.pathname; }
  catch { host = url.replace(/^https?:\/\//,"").split("/")[0]; }
  if (KNOWN[host]) return { ...KNOWN[host], host };
  // Generic derivation from the URL so any link produces something reasonable.
  let slug = path.split("/").filter(Boolean).pop() || host;
  slug = decodeURIComponent(slug).replace(/[-_]+/g," ").replace(/\.\w+$/,"").trim();
  const nameCap = s => s.replace(/\b\w/g, c => c.toUpperCase());
  const title = slug ? nameCap(slug) + " — " + host : host;
  return { title, desc: "Saved from " + host + ". (Description read from the page.)", host };
}

// --- State ---
let bookmarks = [];
let pending = null;

const $ = id => document.getElementById(id);

$("fetchBtn").addEventListener("click", startCapture);
$("url").addEventListener("keydown", e => { if (e.key === "Enter") startCapture(); });
$("saveBtn").addEventListener("click", commitSave);
$("cancelBtn").addEventListener("click", resetCapture);

function startCapture() {
  const url = $("url").value.trim();
  if (!url) { $("url").focus(); return; }
  $("details").classList.remove("show");
  $("fetching").classList.add("show");
  $("fetchBtn").disabled = true;
  setTimeout(() => {
    const meta = simulateFetch(url);
    pending = { url };
    $("title").value = meta.title;
    $("desc").value = meta.desc;
    $("tags").value = "";
    $("note").value = "";
    $("fetching").classList.remove("show");
    $("details").classList.add("show");
    $("fetchBtn").disabled = false;
    $("title").focus();
  }, 850);
}

function commitSave() {
  if (!pending) return;
  const tags = $("tags").value.split(",").map(t => t.trim()).filter(Boolean);
  bookmarks.unshift({
    url: pending.url,
    title: $("title").value.trim() || pending.url,
    desc: $("desc").value.trim(),
    note: $("note").value.trim(),
    tags
  });
  resetCapture();
  render();
}

function resetCapture() {
  pending = null;
  $("url").value = "";
  $("details").classList.remove("show");
  $("fetching").classList.remove("show");
  $("fetchBtn").disabled = false;
  $("url").focus();
}

function esc(s){ return (s||"").replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c])); }

function render() {
  const list = $("list");
  $("count").textContent = bookmarks.length ? "(" + bookmarks.length + ")" : "";
  if (!bookmarks.length) {
    list.innerHTML = '<div class="empty"><div class="big">Nothing saved yet</div>Paste a link above and it will appear here, safe and findable.</div>';
    return;
  }
  list.innerHTML = bookmarks.map(b => `
    <div class="card">
      <p class="title"><a href="${esc(b.url)}" target="_blank" rel="noopener">${esc(b.title)}</a></p>
      <div class="url">${esc(b.url)}</div>
      ${b.desc ? `<p class="desc">${esc(b.desc)}</p>` : ""}
      ${b.note ? `<p class="note">📝 ${esc(b.note)}</p>` : ""}
      ${b.tags.length ? `<div class="tags">${b.tags.map(t => `<span class="tag">#${esc(t)}</span>`).join("")}</div>` : ""}
    </div>`).join("");
}

render();
document.body.setAttribute("data-harness-ready", "true");
</script>
</body>
